struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

static const float PI = 3.14159265;

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv * 2.0 - 1.0;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float r = length(uv);
    float a = atan2(uv.y, uv.x);
    int segments = 6;
    float segAngle = 2.0 * PI / segments;
    a = abs(fmod(a, segAngle) - segAngle * 0.5);
    float2 p = float2(cos(a), sin(a)) * r;
    p += float2(t * 0.3, t * 0.2);
    float v = sin(p.x * 5.0) + sin(p.y * 5.0);
    v += sin((p.x + p.y) * 3.0 + t);
    v += sin(length(p) * 4.0 - t * 2.0);
    v *= 0.25;
    float3 col;
    col.r = 0.5 + 0.5 * sin(v * PI + 0.0);
    col.g = 0.5 + 0.5 * sin(v * PI + 2.094);
    col.b = 0.5 + 0.5 * sin(v * PI + 4.188);
    col *= smoothstep(1.2, 0.3, r);
    return float4(col, 1.0);
}
